"""Authored V2 scenarios. Questions are not LLM outputs or numeric template swaps.

Each family has six distinct tasks and two related but unsupported requests.
Tuple fields: category, question, answer, verbatim supporting policy sentence.
"""


def task(category, question, answer, evidence):
    return {"category": category, "question": question, "answer": answer, "evidence_text": evidence}


def family(slug, title, scope, tasks, negatives, legacy, routing):
    return {"family_id": slug, "title": title, "scope": scope, "tasks": tasks,
            "negative_questions": negatives, "legacy_evidence": legacy, "routing_note": routing}


